UPDATE products SET short_description='<p>Fast, familiar pharmacy essential for fever and mild-to-moderate pain relief labeling.</p>', description='<p>Paracetamol 500 mg tablets are presented as a straightforward everyday analgesic and antipyretic option. This listing focuses on clear pack information, strength, storage and safety notes so customers can identify the product correctly before purchase.</p>', ingredients='<p>Paracetamol 500 mg per tablet. Excipients vary by manufacturer.</p>', usage_info='<p>Use only according to the package label or the advice of a qualified healthcare professional. Check the label carefully before combining with other cold, flu or pain products.</p>', warnings='<p>Do not exceed the labeled dose. Avoid accidental duplication with other products containing paracetamol/acetaminophen. Seek professional advice for liver disease, persistent symptoms, pregnancy, or use in children.</p>', storage_info='<p>Store below 30°C in a dry place, protected from direct light and out of reach of children.</p>', seo_title='Paracetamol 500 mg Tablet | ShasthoCare', seo_description='Fast, familiar pharmacy essential for fever and mild-to-moderate pain relief labeling.' WHERE id=1;
UPDATE products SET short_description='<p>Convenient electrolyte powder sachets intended for preparation with the correct amount of safe drinking water.</p>', description='<p>Oral Rehydration Salts are formulated to replace water and electrolytes lost during dehydration. Each sachet should be prepared exactly according to the pack directions, making this product suitable for home first-aid and travel kits.</p>', ingredients='<p>Glucose and balanced electrolytes in dry powder form. Exact composition should follow the manufacturer label.</p>', usage_info='<p>Dissolve one sachet only in the volume of safe drinking water stated on the pack. Use the prepared solution within the period specified by the manufacturer.</p>', warnings='<p>Incorrect dilution can make the solution unsuitable. Seek medical care for severe dehydration, persistent vomiting, blood in stool, reduced consciousness, or other concerning symptoms.</p>', storage_info='<p>Keep unopened sachets sealed in a cool, dry place away from moisture. Follow the label for storage of prepared solution.</p>', seo_title='Oral Rehydration Salts Sachet | ShasthoCare', seo_description='Convenient electrolyte powder sachets intended for preparation with the correct amount of safe drinking water.' WHERE id=2;
UPDATE products SET short_description='<p>Chewable antacid tablets for occasional acid-related discomfort, presented with clear label-led use guidance.</p>', description='<p>These chewable antacid tablets contain a calcium-carbonate-based blend designed for short-term, occasional relief labeling. The compact pack is convenient for home, office or travel use.</p>', ingredients='<p>Calcium-carbonate-based antacid blend with standard tablet excipients.</p>', usage_info='<p>Chew and use only as directed on the package. Leave appropriate spacing from other medicines when the label or healthcare professional advises it.</p>', warnings='<p>Persistent or frequent symptoms require professional assessment. Ask a healthcare professional about suitability if you have kidney disease, are pregnant, or take regular medicines.</p>', storage_info='<p>Store in a dry place below 30°C with the container tightly closed.</p>', seo_title='Antacid Chewable Tablet | ShasthoCare', seo_description='Chewable antacid tablets for occasional acid-related discomfort, presented with clear label-led use guidance.' WHERE id=3;
